                      key={index}
                      x={x}
                      y="195"
                      className="text-xs fill-slate-500"
                      textAnchor="middle"
                    >
                      {item.mes.split(' ')[0]}
                    </text>
                  );
                })}
              </svg>
            </div>
          </div>
        </div>

        {/* Status dos Quartos */}
        <div className="bg-white dark:bg-slate-800 rounded-xl shadow-lg p-6 border border-slate-200 dark:border-slate-700">
          <h3 className="text-lg font-semibold text-slate-900 dark:text-white mb-4">Status dos Quartos</h3>
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
            <div className="text-center p-4 bg-green-50 dark:bg-green-900/20 rounded-lg">
              <div className="text-2xl font-bold text-green-600 dark:text-green-400">{stats?.quartosDisponiveis || 0}</div>
              <div className="text-sm text-green-600 dark:text-green-400">Disponíveis</div>
            </div>
            <div className="text-center p-4 bg-blue-50 dark:bg-blue-900/20 rounded-lg">
              <div className="text-2xl font-bold text-blue-600 dark:text-blue-400">{stats?.quartosOcupados || 0}</div>
              <div className="text-sm text-blue-600 dark:text-blue-400">Ocupados</div>
            </div>
            <div className="text-center p-4 bg-yellow-50 dark:bg-yellow-900/20 rounded-lg">
              <div className="text-2xl font-bold text-yellow-600 dark:text-yellow-400">{stats?.quartosManutencao || 0}</div>
              <div className="text-sm text-yellow-600 dark:text-yellow-400">Manutenção</div>
            </div>
            <div className="text-center p-4 bg-red-50 dark:bg-red-900/20 rounded-lg">
              <div className="text-2xl font-bold text-red-600 dark:text-red-400">{stats?.quartosSujo || 0}</div>
              <div className="text-sm text-red-600 dark:text-red-400">Sujo</div>
            </div>
          </div>
        </div>
      </div>

      <ErrorModal
        isOpen={showError}
        onClose={() => setShowError(false)}
        title="Erro ao Carregar Dados"
        message={errorMessage}
      />
    </div>
  );
};

export default DashboardAdmin;
